SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "朔方节度使韩洙去世。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p028·原文件第114行", "note": "原文：初，朔方节度使韩洙卒，；核对说明：主初不独具年，新韩氏传明确天成四年作为纪年补证；不猜具体月份或死因。", "status": "draft", "id": "d7dab0ae-306e-599e-8fed-669fd552141e", "subject_id": "77b834be-f439-5a06-8cc9-964a4b99587f", "source_id": "9483009a-07c3-5bc7-b02f-30ef652b0f38"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "主书初追叙；新韩氏传记天成四年（929），确日未载", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p028·原文件第114行", "note": "原文：初，朔方节度使韩洙卒，；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "3a4a11fc-ac46-5f4d-940d-3a4d9d67a4fd", "subject_id": "77b834be-f439-5a06-8cc9-964a4b99587f", "source_id": "9483009a-07c3-5bc7-b02f-30ef652b0f38"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记韩洙：去世的朔方节度使。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p028·原文件第114行", "note": "原文：初，朔方节度使韩洙卒，；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "d1b35fbe-2729-53ee-b4f0-cfafa982434c", "subject_id": "1a67da28-3847-540d-8f32-85c6b9d3e067", "source_id": "9483009a-07c3-5bc7-b02f-30ef652b0f38"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "韩洙：去世的朔方节度使。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p028·原文件第114行", "note": "原文：初，朔方节度使韩洙卒，；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "1fe94559-de26-5933-a20a-ad86f5af64e3", "subject_id": "58b80a26-6f30-5fc1-aef1-eecd6a189eb0", "source_id": "9483009a-07c3-5bc7-b02f-30ef652b0f38"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "新韩氏传将韩洙卒系天成四年。", "citation": "《新五代史》卷四十，段落 xin-wudaishi-b08f244b9241-p001437；EPUB电子本，纸本及异文待核", "note": "原文：天成四年，洙卒，；核对说明：依补书929纪年，不当主十月丁酉死亡日。", "status": "draft", "id": "6dbb74a5-999e-5230-a76e-8025063640a6", "subject_id": "77b834be-f439-5a06-8cc9-964a4b99587f", "source_id": "cce14436-6d13-5a43-8f47-bf7081e8d327"}, {"subject_table": "event", "field_path": "description", "claim_text": "韩洙卒后，韩澄为朔方留后。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p028·原文件第114行", "note": "原文：弟澄为留后。；核对说明：主与新康福传称弟，新韩氏传称子，亲属冲突先作事实引用，不建确定父亲或弟弟边；留后非正式节度使全称。", "status": "draft", "id": "a592d52a-d7ec-5704-a894-8d18c39b6233", "subject_id": "6939454b-2050-5478-a46d-cac05a5aa210", "source_id": "9483009a-07c3-5bc7-b02f-30ef652b0f38"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "韩洙天成四年卒后；确日未载", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p028·原文件第114行", "note": "原文：弟澄为留后。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "149c693a-e685-564a-8f83-aa5eddfda1cc", "subject_id": "6939454b-2050-5478-a46d-cac05a5aa210", "source_id": "9483009a-07c3-5bc7-b02f-30ef652b0f38"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记韩澄：接任留后者。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p028·原文件第114行", "note": "原文：弟澄为留后。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "b711ea56-8d4c-5f48-ad85-0c371dc47ef4", "subject_id": "a7c213d8-dd62-54a6-a9fc-9331b40bb663", "source_id": "9483009a-07c3-5bc7-b02f-30ef652b0f38"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "韩澄：接任留后者。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p028·原文件第114行", "note": "原文：弟澄为留后。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "c713179b-4d9e-5731-af5b-10fed0dd7ce9", "subject_id": "4b04d668-7ebb-5c81-b482-41017490687d", "source_id": "9483009a-07c3-5bc7-b02f-30ef652b0f38"}, {"subject_table": "person", "field_path": "description", "claim_text": "新韩氏传称韩澄为韩洙之子，而主书及新康福传称弟。", "citation": "《新五代史》卷四十，段落 xin-wudaishi-b08f244b9241-p001437；EPUB电子本，纸本及异文待核", "note": "原文：即以洙子澄為朔方軍留後。；核对说明：同书内部亲属口径也有差，保留未定，不据单句构建两套相互冲突亲属关系。", "status": "draft", "id": "0be13ca0-15f4-5dcd-8a30-8e0268c60835", "subject_id": "a7c213d8-dd62-54a6-a9fc-9331b40bb663", "source_id": "cce14436-6d13-5a43-8f47-bf7081e8d327"}, {"subject_table": "person", "field_path": "description", "claim_text": "新康福传称韩洙死、其弟澄立。", "citation": "《新五代史》卷四十六，段落 xin-wudaishi-b08f244b9241-p001748；EPUB电子本，纸本及异文待核", "note": "原文：靈武韓洙死，其弟澄立，；核对说明：与主弟同口径，但与新韩氏传子不同，纸本待核。", "status": "draft", "id": "d9b5cb62-7860-5afd-860e-232d6765c2cc", "subject_id": "a7c213d8-dd62-54a6-a9fc-9331b40bb663", "source_id": "fa846bdb-d3af-52fe-bd49-234d29dfd3cb"}, {"subject_table": "event", "field_path": "description", "claim_text": "定远军使李匡宾聚党据保静镇作乱，朔方不安。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p028·原文件第114行", "note": "原文：未几，定远军使李匡宾聚党据保静镇作乱，朔方不安；；核对说明：未几为韩洙卒及韩澄立后的相对次序，主未独定作乱日；李匡宾主规范，新康作李从宾、新韩作李宾未直接合正式别名或造第二次叛乱。", "status": "draft", "id": "8c40a087-f2d0-5265-a6bb-70a097659655", "subject_id": "12358d42-9933-5033-85ff-628c79f93180", "source_id": "9483009a-07c3-5bc7-b02f-30ef652b0f38"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "背景或追叙；本句确年日未载", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p028·原文件第114行", "note": "原文：未几，定远军使李匡宾聚党据保静镇作乱，朔方不安；；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "e2cbe45d-5ab0-58d0-a75f-7d1fdfa483ea", "subject_id": "12358d42-9933-5033-85ff-628c79f93180", "source_id": "9483009a-07c3-5bc7-b02f-30ef652b0f38"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李匡宾：据保静镇作乱的定远军使。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p028·原文件第114行", "note": "原文：未几，定远军使李匡宾聚党据保静镇作乱，朔方不安；；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "03259c75-f447-5f98-a604-01290b528f00", "subject_id": "0b36580e-7115-5404-91ce-3088fe48a1cd", "source_id": "9483009a-07c3-5bc7-b02f-30ef652b0f38"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李匡宾：据保静镇作乱的定远军使。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p028·原文件第114行", "note": "原文：未几，定远军使李匡宾聚党据保静镇作乱，朔方不安；；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "81b69ba5-34d6-5932-851f-6839d5221d98", "subject_id": "d617610c-dabc-53ed-8f87-60f738ae16f1", "source_id": "9483009a-07c3-5bc7-b02f-30ef652b0f38"}, {"subject_table": "event", "field_path": "description", "claim_text": "新康福传称同一请帅背景为偏将李从宾作乱。", "citation": "《新五代史》卷四十六，段落 xin-wudaishi-b08f244b9241-p001748；EPUB电子本，纸本及异文待核", "note": "原文：而偏將李從賓作亂。；核对说明：主定远军使李匡宾与新李从宾职名和人名差保留，暂对应同案补证，不外推其他同名人物身份。", "status": "draft", "id": "063c61d6-179c-5784-ad81-0fdfe4e7e72f", "subject_id": "12358d42-9933-5033-85ff-628c79f93180", "source_id": "fa846bdb-d3af-52fe-bd49-234d29dfd3cb"}, {"subject_table": "event", "field_path": "description", "claim_text": "新韩氏传记其将李宾作乱。", "citation": "《新五代史》卷四十，段落 xin-wudaishi-b08f244b9241-p001437；EPUB电子本，纸本及异文待核", "note": "原文：其將李賓作亂，；核对说明：李宾与李匡宾、李从宾差不等单纯繁简转换；定位同案但不增确定告发或亲属。", "status": "draft", "id": "9d1fb5a1-e2f0-50d8-a827-7f03aa09dcd4", "subject_id": "12358d42-9933-5033-85ff-628c79f93180", "source_id": "cce14436-6d13-5a43-8f47-bf7081e8d327"}, {"subject_table": "event", "field_path": "description", "claim_text": "韩澄遣使持绢表，请朝廷任命朔方主帅。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p028·原文件第114行", "note": "原文：冬，十月，丁酉，韩澄遣使赍绢表乞朝廷命帅。；核对说明：使者未名；请帅不等当天康福已经到镇。", "status": "draft", "id": "48d990ef-8d55-5624-a433-0fafd8bb48c5", "subject_id": "2e627cf9-f0e5-5807-83b4-bba3bca5a254", "source_id": "9483009a-07c3-5bc7-b02f-30ef652b0f38"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "929年十月丁酉", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p028·原文件第114行", "note": "原文：冬，十月，丁酉，韩澄遣使赍绢表乞朝廷命帅。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "0aae4631-2617-596c-ba1a-7a22a89f36a6", "subject_id": "2e627cf9-f0e5-5807-83b4-bba3bca5a254", "source_id": "9483009a-07c3-5bc7-b02f-30ef652b0f38"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "韩澄：上表请帅者。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p028·原文件第114行", "note": "原文：冬，十月，丁酉，韩澄遣使赍绢表乞朝廷命帅。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "54dc7d16-4f2a-5c3e-84d0-d5ccbbd78518", "subject_id": "72b8f351-68a0-5edc-8c01-0dd95119aa2d", "source_id": "9483009a-07c3-5bc7-b02f-30ef652b0f38"}, {"subject_table": "event", "field_path": "description", "claim_text": "李嗣源常召康福入便殿问时事，康福以胡语回答。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p028·原文件第114行", "note": "原文：前磁州刺史康福，善胡语，上退朝，多召入便殿，访以时事，福以胡语对；；核对说明：多召为往事习惯，未具每次年月，不作为929新任磁州刺史；胡语未明确语言种类。", "status": "draft", "id": "abdf2319-0e09-53d7-b74a-c464bfb830cc", "subject_id": "e042b714-01ca-5e47-9a26-868903de315f", "source_id": "9483009a-07c3-5bc7-b02f-30ef652b0f38"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "背景或追叙；本句确年日未载", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p028·原文件第114行", "note": "原文：前磁州刺史康福，善胡语，上退朝，多召入便殿，访以时事，福以胡语对；；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "177bd7b8-b8fc-5f92-82cd-407389dcd326", "subject_id": "e042b714-01ca-5e47-9a26-868903de315f", "source_id": "9483009a-07c3-5bc7-b02f-30ef652b0f38"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李嗣源：召问时事者。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p028·原文件第114行", "note": "原文：前磁州刺史康福，善胡语，上退朝，多召入便殿，访以时事，福以胡语对；；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "6d7abef6-55f5-57e1-b3f7-72552a2eea1f", "subject_id": "5d1886ff-b3ec-56f6-a154-b5633c294037", "source_id": "9483009a-07c3-5bc7-b02f-30ef652b0f38"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李嗣源：召问时事者。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p028·原文件第114行", "note": "原文：前磁州刺史康福，善胡语，上退朝，多召入便殿，访以时事，福以胡语对；；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "bcf31aa2-a21e-594d-8568-ecc82298269d", "subject_id": "7eef492c-a8cb-52c2-ac39-503875a476b8", "source_id": "9483009a-07c3-5bc7-b02f-30ef652b0f38"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记康福：善胡语、以胡语答者。", "citation": "卷276·天成四年（929）·zztj-v276-y0929-p028·原文件第114行", "note": "原文：前磁州刺史康福，善胡语，上退朝，多召入便殿，访以时事，福以胡语对；；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "f25a304f-b319-56a0-9893-267b6d4b2dba", "subject_id": "7419fd99-6e0a-53d2-8c35-3a4c51f654d7", "so